import { useMemo, useState } from 'react'
import map from '../data/scMap.json'

// Real county boundaries (U.S. Census via us-atlas), regenerated by
// scripts/generate-sc-map.mjs. Regions are SCAiL's planning regions.
export const REGIONS = [
  {
    name: 'Upstate',
    color: 'var(--color-sea)',
    blurb: 'Blue Ridge foothills down to the I-85 manufacturing corridor, where factory floors are adopting AI fastest.',
    places: 'Greenville · Spartanburg · Anderson · Rock Hill',
  },
  {
    name: 'Midlands',
    color: 'var(--color-sun)',
    blurb: 'The capital region and SCAiL’s home base. Our first classes start here, in the communities around Columbia and Irmo.',
    places: 'Columbia · Irmo · Lexington · Sumter · Aiken',
  },
  {
    name: 'Pee Dee',
    color: '#7f9be0',
    blurb: 'Farm country and the Grand Strand: small towns where an AI class may be the first anyone has offered.',
    places: 'Florence · Darlington · Dillon · Myrtle Beach',
  },
  {
    name: 'Lowcountry',
    color: '#ee8c6f',
    blurb: 'Sea Islands, the port, and rural counties along the coast, with deep roots and a fast-changing economy.',
    places: 'Charleston · Beaufort · Walterboro · Hampton',
  },
]

// Labels that sit left of their dot (to avoid the coast edge or a neighbour)
const LEFT_LABELS = new Set(['Irmo', 'Myrtle Beach'])

const colorOf = Object.fromEntries(REGIONS.map((r) => [r.name, r.color]))

export default function SCMap({ className = '' }) {
  const [active, setActive] = useState('Midlands') // selected region
  const [hover, setHover] = useState(null) // hovered county

  const counties = map.counties
  const inRegion = useMemo(() => counties.filter((c) => c.region === active), [counties, active])
  const region = REGIONS.find((r) => r.name === active)
  const hovered = hover && counties.find((c) => c.id === hover)

  return (
    <div className={`grid gap-8 lg:grid-cols-[1fr_minmax(280px,360px)] lg:items-center ${className}`}>
      {/* Map */}
      <figure className="relative">
        <svg
          viewBox={map.viewBox}
          className="w-full h-auto drop-shadow-[0_24px_40px_rgba(5,15,36,.35)]"
          role="img"
          aria-label={`Map of South Carolina's 46 counties. ${active} region highlighted.`}
          onMouseLeave={() => setHover(null)}
        >
          {counties.map((c) => {
            const on = c.region === active
            const isHover = c.id === hover
            return (
              <path
                key={c.id}
                d={c.d}
                fill={colorOf[c.region]}
                fillOpacity={isHover ? 1 : on ? 0.92 : 0.22}
                stroke="var(--paper)"
                strokeWidth={isHover ? 2.2 : 1}
                strokeLinejoin="round"
                className="cursor-pointer transition-[fill-opacity] duration-300"
                onMouseEnter={() => setHover(c.id)}
                onClick={() => setActive(c.region)}
              >
                <title>{`${c.name} County — ${c.region}`}</title>
              </path>
            )
          })}
          <path d={map.outline} fill="none" stroke="var(--ink)" strokeOpacity="0.55" strokeWidth="1.6" strokeLinejoin="round" />

          {map.cities.map((c) => {
            const capital = c.name === 'Columbia'
            return (
              <g key={c.name} transform={`translate(${c.x} ${c.y})`} className="pointer-events-none">
                {capital ? (
                  <path d="M0 -8 L2.3 -2.5 L8 -2.5 L3.4 1 L5.2 6.6 L0 3.2 L-5.2 6.6 L-3.4 1 L-8 -2.5 L-2.3 -2.5Z" fill="var(--ink)" />
                ) : (
                  <circle r="3.5" fill="var(--ink)" />
                )}
                <text
                  x={LEFT_LABELS.has(c.name) ? -9 : 9}
                  y={c.name === 'Irmo' ? -6 : 4}
                  textAnchor={LEFT_LABELS.has(c.name) ? 'end' : 'start'}
                  fontSize="15"
                  fontWeight="600"
                  fill="var(--ink)"
                  stroke="var(--paper)"
                  strokeWidth="3.5"
                  paintOrder="stroke"
                  style={{ fontFamily: 'var(--font-sans)' }}
                >
                  {c.name}
                </text>
              </g>
            )
          })}
        </svg>

        {/* hover readout */}
        <figcaption
          className="pointer-events-none absolute left-2 top-2 rounded-full border border-line bg-surface/90 px-3.5 py-1.5 text-sm backdrop-blur transition-opacity duration-200"
          style={{ opacity: hovered ? 1 : 0 }}
          aria-live="polite"
        >
          {hovered && (
            <>
              <span className="font-semibold">{hovered.name} County</span>
              <span className="text-muted"> · {hovered.region}</span>
            </>
          )}
        </figcaption>
      </figure>

      {/* Region panel */}
      <div>
        <div className="flex flex-wrap gap-2" role="tablist" aria-label="Regions">
          {REGIONS.map((r) => (
            <button
              key={r.name}
              role="tab"
              aria-selected={active === r.name}
              onClick={() => setActive(r.name)}
              className={`inline-flex items-center gap-2 rounded-full border px-3.5 py-1.5 text-sm font-semibold transition-colors ${
                active === r.name ? 'border-ink bg-ink text-paper' : 'border-line text-ink-soft hover:border-ink/40'
              }`}
            >
              <span className="h-2.5 w-2.5 rounded-full" style={{ background: r.color }} />
              {r.name}
            </button>
          ))}
        </div>

        <div className="mt-6" role="tabpanel" aria-label={region.name}>
          <p className="font-display text-5xl leading-none">
            {inRegion.length}
            <span className="ml-2 align-middle font-sans text-base text-muted">counties</span>
          </p>
          <p className="mt-4 text-ink-soft">{region.blurb}</p>
          <p className="mt-3 eyebrow text-muted">{region.places}</p>
          <ul className="mt-5 flex flex-wrap gap-1.5" aria-label={`Counties in the ${region.name}`}>
            {inRegion.map((c) => (
              <li
                key={c.id}
                onMouseEnter={() => setHover(c.id)}
                onMouseLeave={() => setHover(null)}
                className={`rounded-md px-2 py-0.5 text-[13px] transition-colors cursor-default ${
                  hover === c.id ? 'bg-ink text-paper' : 'bg-surface-2 text-ink-soft'
                }`}
              >
                {c.name}
              </li>
            ))}
          </ul>
        </div>
      </div>
    </div>
  )
}
